function scr_menu(){
// menu helpers live here (navigation, submenus, transitions)
}

function assign_player_controls() {
    var gp_count = 0;
    for (var i = 0; i < 3; i++) {
        if (i == 0) {
            player_controls[i] = (gamepad_is_connected(0)) ? 0 : -1;
        } else {
            var found = false;
            for (var g = 1; g < 8; g++) {
                if (gamepad_is_connected(g)) {
                    player_controls[i] = g;
                    found = true;
                    global.max_players++;
                    break;
                }
            }
            if (!found) player_controls[i] = -1;
        }
    }
}

/**
* @file particle_engine.js
* @brief Sets up and manages a particle engine system for use in a game.
*/
function setup_particle_engine() {
    global.ParticleEngine = {
        sysTop: part_system_create(),
        sysBot: part_system_create(),
        partList: [],
        init: function(depthHigh=-3000, depthLow=0){ part_system_depth(self.sysTop, depthHigh); part_system_depth(self.sysBot, depthLow); },
        addPart: function(part){ array_push(self.partList, part); },
        destroy: function(){ part_system_destroy(self.sysTop); part_system_destroy(self.sysBot); },
        burstBox: function(x1,y1,x2,y2,top,part_id,number){ var sys = top?self.sysTop:self.sysBot; repeat(number){ var xx = irandom_range(x1,x2); var yy = irandom_range(y1,y2); part_particles_create(sys,xx,yy,part_id,1); } }
    };
    global.ParticleEngine.init();
}

